CREATE OR REPLACE FUNCTION public.account_enabled(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = _user_id AND (u.banned_until IS NULL OR u.banned_until <= now())) AND NOT EXISTS (SELECT 1 FROM public.customers c WHERE c.user_id = _user_id AND c.archived_at IS NOT NULL) $$;
REVOKE ALL ON FUNCTION public.account_enabled(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.account_enabled(uuid) TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.account_enabled(_user_id) AND EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
CREATE OR REPLACE FUNCTION public.is_staff(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.account_enabled(_user_id) AND EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role IN ('superuser','admin','operator')) $$;
CREATE OR REPLACE FUNCTION public.owns_customer(_customer_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.customers WHERE id = _customer_id AND user_id = auth.uid() AND archived_at IS NULL) AND public.account_enabled(auth.uid()) $$;
CREATE OR REPLACE FUNCTION public.guard_customer_operations() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE c public.customers; BEGIN SELECT * INTO c FROM public.customers WHERE id = NEW.customer_id; IF c.archived_at IS NOT NULL THEN RAISE EXCEPTION 'Archived accounts cannot create requests'; END IF; IF TG_TABLE_NAME = 'pre_orders' AND c.status <> 'VERIFIED' THEN RAISE EXCEPTION 'Verification is required before ordering'; END IF; IF TG_TABLE_NAME = 'tickets' THEN IF c.status <> 'VERIFIED' AND NEW.category NOT IN ('GENERAL','BILLING','REACTIVATION') THEN RAISE EXCEPTION 'Verification is required for operational tickets'; END IF; IF NEW.category = 'VISIT_DC' AND (coalesce(trim(NEW.details->>'visitors'),'') = '' OR coalesce(trim(NEW.details->>'identity_numbers'),'') = '' OR coalesce(trim(NEW.details->>'schedule'),'') = '') THEN RAISE EXCEPTION 'Complete visitor identities and schedule are required'; END IF; IF NEW.category = 'GOODS_IN' AND (coalesce(trim(NEW.details->>'device_type'),'') = '' OR coalesce(trim(NEW.details->>'brand_model'),'') = '' OR coalesce(trim(NEW.details->>'serial_number'),'') = '' OR coalesce(trim(NEW.details->>'rack_u'),'') = '') THEN RAISE EXCEPTION 'Complete device and rack details are required'; END IF; IF NEW.category = 'GOODS_OUT' AND (coalesce(trim(NEW.details->>'withdrawal_details'),'') = '' OR coalesce(trim(NEW.details->>'serial_number'),'') = '' OR coalesce(trim(NEW.details->>'removal_date'),'') = '' OR NEW.attachment_path IS NULL) THEN RAISE EXCEPTION 'Withdrawal details, date and authorization letter are required'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_preorder_creation BEFORE INSERT ON public.pre_orders FOR EACH ROW EXECUTE FUNCTION public.guard_customer_operations();
CREATE TRIGGER guard_ticket_creation BEFORE INSERT ON public.tickets FOR EACH ROW EXECUTE FUNCTION public.guard_customer_operations();
CREATE OR REPLACE FUNCTION public.guard_ticket_reply() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF EXISTS (SELECT 1 FROM public.tickets WHERE id = NEW.ticket_id AND status = 'CLOSED') THEN RAISE EXCEPTION 'Closed tickets do not accept replies'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_ticket_message BEFORE INSERT ON public.ticket_messages FOR EACH ROW EXECUTE FUNCTION public.guard_ticket_reply();
CREATE OR REPLACE FUNCTION public.revoke_inactive_epass() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.status <> 'APPROVED' THEN NEW.epass_code := NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER revoke_ticket_epass BEFORE UPDATE ON public.tickets FOR EACH ROW EXECUTE FUNCTION public.revoke_inactive_epass();
ALTER POLICY "Legal docs: owner delete" ON storage.objects USING (bucket_id = 'legal-documents' AND public.is_staff(auth.uid()));
ALTER POLICY "Legal docs: owner read" ON storage.objects USING (bucket_id = 'legal-documents' AND (storage.foldername(name))[1] = auth.uid()::text AND public.account_enabled(auth.uid()));
ALTER POLICY "Legal docs: owner write" ON storage.objects WITH CHECK (bucket_id = 'legal-documents' AND (storage.foldername(name))[1] = auth.uid()::text AND public.account_enabled(auth.uid()));
REVOKE UPDATE ON public.notifications FROM authenticated;
GRANT UPDATE (read_at) ON public.notifications TO authenticated;